"""Respiratory half of the original respiratory/CNS infection chapter."""
from qbank_authoring import question,ref,finalize
CP=ref('ATS/IDSA Adult Community-Acquired Pneumonia Guideline, 2019—Severity and Empirical Regimens','https://pmc.ncbi.nlm.nih.gov/articles/PMC6812437/')
CU=ref('ATS CAP Guideline Update, 2025','https://doi.org/10.1164/rccm.202507-1692ST')
LG=ref('CDC: Laboratory Testing for Legionella, 2026','https://www.cdc.gov/legionella/php/laboratories/index.html')
LT=ref('CDC: Clinical Guidance for Legionella Infections','https://www.cdc.gov/legionella/hcp/clinical-guidance/index.html')
FL=ref('CDC: Influenza Antiviral Medications—Clinician Summary','https://www.cdc.gov/flu/hcp/antivirals/summary-clinicians.html')
HV=ref('ATS/IDSA: Hospital- and Ventilator-Associated Pneumonia','https://www.idsociety.org/practice-guideline/hap_vap/')
PE=ref('BTS Pleural Disease Guideline, 2023','https://thorax.bmj.com/content/78/Suppl_3/s1.long')
PT=ref('CDC: Treatment of Pertussis','https://www.cdc.gov/pertussis/hcp/clinical-care/index.html')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which finding is a major severe-CAP criterion that supports ICU-level assessment?', 'Septic shock requiring vasopressors',[
 ('Age over 65 alone','Age affects risk but is not itself a major ATS/IDSA severe-CAP criterion.'),('An isolated mild leukocytosis','This does not establish severe CAP.'),('A small single-lobe infiltrate without physiological compromise','Radiographic extent alone in this form is insufficient.')],
 'Physiological support needs outweigh a simple outpatient score', '**Vasopressor-dependent shock and invasive ventilation are major severe-CAP criteria.**',['Multiple minor criteria also identify severe disease.','Clinical judgment is required even when a formal score is low.'], '**Escalate monitoring and therapy promptly.**',['Assess oxygenation, perfusion and complications.','Obtain appropriate microbiology without delaying urgent treatment.'],[['Major','Vasopressor shock or invasive ventilation'],['Minor','Combined physiological/laboratory criteria'],['Disposition','Severity and clinical judgment']],[CP])
q('A younger adult has severe hypoxemia from CAP but a low age-weighted mortality score. What is the best disposition principle?', 'Use oxygenation, support needs and clinical judgment rather than relying on the score alone',[
 ('Discharge automatically because age lowers the score','A low numerical score does not override physiological danger.'),('Wait until hypotension develops before considering admission','Respiratory failure is independently important.'),('Use the chest-film side alone to decide admission','Laterality does not replace physiological assessment.')],
 'Prediction scores do not capture every immediate care requirement', '**PSI and CURB-type tools estimate selected risks.**',['They can understate a young patient’s acute support need.','Social support and ability to take treatment also affect disposition.'], '**Match the care setting to the actual clinical threat.**',['Reassess deterioration and need for respiratory support.','Do not use a single score as a mandatory discharge instruction.'],[['Score','Decision aid'],['Hypoxemia','Direct support need'],['Disposition','Integrated clinical assessment']],[CP],style='clinical_scenario')
q('For hospitalized nonsevere CAP without MRSA or Pseudomonas risk, which is a standard empirical regimen strategy?', 'An appropriate beta-lactam plus a macrolide, or a suitable respiratory fluoroquinolone',[
 ('Metronidazole alone','It does not cover the expected CAP spectrum.'),('Vancomycin alone','It leaves important usual and atypical pathogens uncovered.'),('Aminoglycoside monotherapy','It is not a standard CAP strategy.')],
 'Empirical treatment should cover the expected syndrome without unnecessary breadth', '**A beta-lactam/macrolide combination covers usual and atypical groups.**',['A respiratory fluoroquinolone is an alternative in appropriate patients.','Allergy, QT risk, interactions and local susceptibility influence choice.'], '**Refine treatment when microbiology and response are available.**',['Broaden only for relevant resistance or severity risks.','Use the current duration guidance once stability is reached.'],[['Combination','Beta-lactam plus macrolide'],['Alternative','Respiratory fluoroquinolone'],['Selection','Patient and local factors']],[CP])
q('A patient develops rapidly progressive necrotizing pneumonia after influenza, with shock and cavitation. Which additional empirical consideration is important?', 'MRSA coverage while obtaining appropriate microbiology and assessing other likely pathogens',[
 ('Assume every post-influenza pneumonia is viral only','Secondary bacterial pneumonia can be severe.'),('Add only anaerobic coverage while excluding S. aureus','The clinical pattern raises concern for staphylococcal disease.'),('Withhold antibacterial treatment until the influenza test becomes negative','This would delay treatment of suspected bacterial coinfection.')],
 'A preceding virus can change the bacterial differential', '**S. aureus, including MRSA, can cause severe post-influenza pneumonia.**',['Cavitation and rapid deterioration are concerning.','Other bacterial pathogens remain possible.'], '**Treat severe illness promptly and narrow from evidence.**',['Use suitable MRSA-active pneumonia therapy.','Assess pleural infection and other complications.'],[['Trigger','Influenza'],['Pattern','Rapid necrotizing/cavitating pneumonia'],['Empirical plan','Include relevant MRSA coverage']],[CP],style='clinical_scenario')
q('Which factor particularly supports assessing Pseudomonas coverage in CAP?', 'Previous respiratory isolation of Pseudomonas, interpreted with current illness and local data',[
 ('Any health-care contact ever, irrespective of details','The old blanket health-care-associated label is insufficient.'),('Age above 40 alone','This is not a specific validated Pseudomonas indication.'),('A positive influenza test as proof of Pseudomonas','A viral result does not identify a bacterial species.')],
 'Resistance prediction should be specific and locally informed', '**Prior respiratory isolation is an important risk signal.**',['Recent hospitalization with parenteral antibiotics can also matter.','Structural lung disease and prior history contribute to individual assessment.'], '**Obtain cultures when broad resistant-pathogen coverage is used.**',['Narrow treatment when results and response support it.','Do not give antipseudomonal therapy solely from a vague setting label.'],[['Strong clue','Prior respiratory isolate'],['Additional context','Recent antibiotics and local risk'],['Stewardship','Culture and reassess']],[CP])
q('After a witnessed large-volume aspiration during anesthesia, a patient develops abrupt hypoxemia that improves substantially within 24–48 hours without evidence of bacterial infection. What is most consistent?', 'Chemical aspiration pneumonitis',[
 ('Established bacterial aspiration pneumonia in every such episode','Chemical injury can occur without bacterial infection.'),('Latent TB reactivation within minutes','That time course is incompatible.'),('A mandatory indication for prolonged anaerobic antibiotics regardless of course','Antibiotics are not automatically required for a resolving chemical injury.')],
 'Aspiration can cause sterile chemical injury or infection', '**Immediate lung injury after gastric aspiration may be pneumonitis.**',['Supportive care and close reassessment are central.','Persistent or evolving infectious findings can change the diagnosis.'], '**Do not confuse a rapid aspiration event with proof of bacterial pneumonia.**',['Assess oxygenation and airway needs.','Reevaluate if fever, infiltrates or deterioration persist.'],[['Pneumonitis','Chemical injury'],['Pneumonia','Infection'],['Course','Repeated assessment distinguishes evolving disease']],[CP],style='clinical_scenario')
q('When should additional anaerobic coverage particularly be considered in suspected aspiration-related pneumonia?', 'When lung abscess or empyema is suspected',[
 ('For every aspiration event regardless of evidence of infection','This leads to unnecessary treatment.'),('Never, even with a lung abscess','The complication changes the microbial and source-control considerations.'),('Only when a viral swab is positive','That is not the relevant indication.')],
 'Routine aspiration does not automatically imply a need for extra anaerobic therapy', '**ATS/IDSA advises against routine added anaerobic coverage without abscess or empyema.**',['The selected main antibiotic may already have anaerobic activity.','Dental and anatomical factors can inform the full assessment.'], '**Identify complications requiring drainage or prolonged treatment.**',['Image when the course or radiograph suggests a collection.','Avoid duplicate spectrum without a clinical reason.'],[['Uncomplicated aspiration pneumonia','No routine added anaerobic drug'],['Abscess/empyema','Reassess anaerobes and source control'],['Regimen','Check existing activity']],[CP])
q('A patient has severe pneumonia after hotel travel. Which testing strategy best evaluates Legionella?', 'Urinary antigen together with lower-respiratory culture or molecular testing',[
 ('Urinary antigen alone excludes every species and serogroup when negative','It usually detects L. pneumophila serogroup 1 only.'),('Routine blood-culture negativity excludes Legionella','It does not.'),('A positive urinary antigen directly supplies the full susceptibility profile','It does not provide an isolate or full susceptibility information.')],
 'Paired tests improve breadth and public-health usefulness', '**The urinary antigen is rapid but has a restricted detection range.**',['Lower-respiratory PCR or culture can detect a wider range.','Culture supports comparison with environmental isolates in outbreaks.'], '**Collect the appropriate specimens without delaying severe-pneumonia therapy.**',['A negative urinary test does not exclude all Legionella.','Report relevant travel or water-system exposure.'],[['Urine antigen','Usually pneumophila serogroup 1'],['Respiratory test','Broader detection'],['Culture','Outbreak isolate comparison']],[LG],style='clinical_scenario')
q('Which class provides appropriate directed activity against Legionella in a suitable patient?', 'A macrolide or respiratory fluoroquinolone',[
 ('A beta-lactam alone as reliable directed therapy','Conventional beta-lactam treatment does not adequately address Legionella.'),('Vancomycin alone','It does not provide suitable Legionella coverage.'),('Metronidazole alone','It is not effective directed therapy.')],
 'An intracellular pathogen needs an active appropriately penetrating agent', '**Azithromycin or a suitable respiratory fluoroquinolone are common options.**',['Severity, interactions and contraindications influence the choice.','Treatment length is individualized to illness and immune status.'], '**Review the full empirical regimen when the diagnosis is established.**',['Stop unnecessary agents when safe.','Assess complications and response in severe disease.'],[['Macrolide','Legionella-active option'],['Respiratory fluoroquinolone','Alternative active option'],['Beta-lactam alone','Inadequate directed strategy']],[LT])
q('A patient is hospitalized with suspected influenza pneumonia on day five of illness. Which antiviral principle is appropriate?', 'Start oseltamivir promptly when indicated; hospitalization or severe illness can justify treatment beyond 48 hours',[
 ('Never treat after 48 hours regardless of severity','The early-outpatient window does not impose that limit in severe or hospitalized illness.'),('Wait for definitive test results before treating every high-risk case','This can delay benefit.'),('Use antibiotics alone because antivirals work only before symptoms','Antivirals can benefit symptomatic influenza.')],
 'The greatest early benefit does not define an absolute late-treatment prohibition', '**Hospitalized and severe cases are priority groups for antiviral treatment.**',['Adjust dosing for renal function where needed.','A bacterial coinfection can require simultaneous antibacterial therapy.'], '**Use appropriate molecular testing and infection-control measures.**',['Do not assume a positive influenza result explains every complication.','Reassess respiratory status and secondary infection.'],[['Hospitalized/severe','Treat promptly when indicated'],['Timing','Benefit can remain after 48 hours'],['Coinfection','Assess bacterial disease separately']],[FL],style='clinical_scenario')
q('A healthy outpatient has nonsevere CAP, a positive respiratory-virus test and no comorbidity or other concerning bacterial evidence. What option does ATS 2025 support?', 'Consider withholding empirical antibiotics after individualized assessment and with follow-up',[
 ('Every positive viral test in every patient permits withholding antibiotics','Hospitalization, comorbidity and severe disease change the recommendation.'),('All viral-positive outpatients need indefinite broad antibacterial therapy','This is excessive for the specified low-risk context.'),('A viral test rules out bacterial coinfection with certainty','It does not; the recommendation requires clinical assessment.')],
 'Virus detection changes probability rather than proving absence of bacteria', '**ATS 2025 differentiates selected low-risk outpatients from higher-risk groups.**',['Clinical severity and comorbidity affect the decision.','Close follow-up is essential if antibiotics are withheld.'], '**Reassess promptly if the course worsens.**',['Explain warning symptoms and access to review.','Do not extrapolate this selected-patient option to severe CAP.'],[['Selected outpatient','May avoid empirical antibiotics'],['Higher-risk patient','Different balance'],['Viral result','Not absolute exclusion of coinfection']],[CU],style='clinical_scenario')
q('What antibiotic-duration option does ATS 2025 suggest for selected nonsevere CAP patients who reach clinical stability?', 'A course shorter than five days, with a minimum of three days, when the clinical context is suitable',[
 ('Three days for every severe or complicated pneumonia','Severe disease and complications require different assessment.'),('At least 14 days for every uncomplicated stable case','This is not routinely necessary.'),('Stop after one dose whenever temperature falls','That is not the recommended minimum course.')],
 'Clinical stability supports shorter treatment in selected nonsevere disease', '**The 2025 update permits a shorter minimum than the older five-day rule.**',['Vital signs, oxygenation, mentation and oral intake inform stability.','Pathogen and complications can require longer therapy.'], '**Use an individualized completion decision.**',['Do not apply the short course to uncontrolled infection or empyema.','Provide follow-up instructions.'],[['Eligible group','Stable nonsevere CAP'],['Option','Less than five, minimum three days'],['Exceptions','Severe or complicated/pathogen-specific disease']],[CU])
q('Which corticosteroid statement matches the ATS 2025 adult CAP update?', 'Steroids are suggested for severe CAP in appropriate patients, while routine use is discouraged in nonsevere CAP',[
 ('Steroids are mandatory for every mild outpatient cough','This is outside the recommendation.'),('The severe-CAP recommendation automatically applies to influenza pneumonia','Influenza is an important exclusion and separate evidence context.'),('Steroids replace antibiotics in severe bacterial CAP','They are adjunctive, not antimicrobial replacement.')],
 'Severity and etiology determine the benefit-risk balance', '**The newer guidance distinguishes severe from nonsevere CAP.**',['Assess contraindications and important viral exceptions.','Septic shock can provide a separate steroid indication.'], '**Monitor glucose and adverse effects.**',['Use a suitable protocol rather than an arbitrary prolonged course.','Continue appropriate pathogen treatment and supportive care.'],[['Severe CAP','Selected adjunctive use'],['Nonsevere CAP','No routine systemic steroids'],['Influenza','Do not automatically extrapolate']],[CU])
q('How should empirical HAP/VAP coverage be selected?', 'Use local susceptibility data, prior cultures, recent IV antibiotics and severity rather than onset timing alone',[
 ('Early onset guarantees susceptibility to every narrow antibiotic','Patient and unit resistance risks can still be substantial.'),('Every case requires the same maximal combination indefinitely','Coverage should be reassessed and narrowed.'),('A single normal white-cell count excludes VAP','No isolated routine marker reliably excludes it.')],
 'Hospital pathogens reflect both patient exposure and the local ecology', '**Prior IV antibiotics and known colonization can increase MDR risk.**',['Shock and local prevalence influence empirical breadth.','Use suitable respiratory samples to refine treatment.'], '**Reassess diagnosis, dose and spectrum.**',['Distinguish colonization from a compatible pneumonia syndrome.','De-escalate when results and clinical response permit.'],[['Patient','Prior cultures and antibiotics'],['Unit','Local antibiogram'],['Course','Severity and response']],[HV])
q('A patient with pneumonia has frank pus in the pleural space. Which management principle is central?', 'Antibiotics plus pleural drainage/source control',[
 ('Antibiotics alone regardless of collection size and persistence','Established empyema generally needs drainage.'),('Repeated antipyretics without source treatment','They do not control the infection.'),('Treat the fluid as a sterile transudate without further assessment','Pus indicates pleural infection.')],
 'A pleural collection is a separate anatomical treatment target', '**Empyema requires effective antimicrobial and drainage management.**',['Ultrasound helps characterize and safely access fluid.','Loculations and inadequate drainage can require additional therapy or surgery.'], '**Monitor resolution and drain function.**',['Tailor antibiotics to source and microbiology.','Escalate when the collection persists or the patient fails to improve.'],[['Antibiotics','Treat organisms'],['Drainage','Controls the pleural source'],['Persistent disease','Assess loculation and further intervention']],[PE],style='clinical_scenario')
q('An adult has prolonged paroxysmal cough with post-tussive vomiting and household exposure. Which treatment principle applies to suspected pertussis?', 'Use an appropriate macrolide when indicated and address transmission and high-risk contacts',[
 ('A late antibiotic course always immediately stops the established cough','Symptoms can persist despite organism clearance.'),('Beta-lactams are the standard preferred directed drugs','Macrolides are standard options.'),('Vaccination history completely excludes pertussis','Protection can wane and vaccinated people can still become infected.')],
 'Pertussis treatment addresses both disease timing and transmission', '**Early antibiotics are more likely to modify the illness.**',['Later treatment decisions consider duration and vulnerable contacts.','Use current guidance when macrolide resistance or contraindications are relevant.'], '**Coordinate testing, precautions and contact prevention.**',['Protect infants and others at high risk of severe disease.','Explain that cough resolution may be slow.'],[['Syndrome','Paroxysms and post-tussive vomiting'],['Drug','Appropriate macrolide'],['Public health','Transmission and high-risk contacts']],[PT],style='clinical_scenario')

if __name__=='__main__':print('Respiratory infection questions: '+str(len(rows)))
